/* Original supplementary career events. These are project rules, not book entries. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.TravellerAdditionalEvents=api})(typeof globalThis==='object'?globalThis:this,function(){
'use strict';
const effect=(type,data={})=>({type,...data}),rel=kind=>effect('relation',{kind}),skill=name=>effect('reward',{name,level:1}),mod=(scope,value,label)=>effect('modifier',{scope,value,label}),end=(effects=[])=>({effects,next:'advancement'});
const check=(id,label,name,attribute,success,failure)=>({id,label,skill:name,attribute,target:8,success:end(success),failure:end(failure)});
const events=[
{id:'storm-survey',career:'scout',number:4,art:'storm-survey',title:'Survey through the storm',text:'A violent storm closes over an unexplored plateau. Keep the survey team together with Survival 8+: gain Survival 1 and a Contact. Failure loses valuable survey time: DM−1 to this term’s Advancement.',choices:[check('weather','Guide the team through the storm','Выживание',3,[skill('Выживание'),rel('Контакт')],[mod('advancement',-1,'Survey delayed')])]},
{id:'storm-evacuation',career:'army',number:3,art:'storm-evacuation',title:'Evacuation before the storm',text:'A remote outpost lies in the path of a catastrophic storm. Leadership 8+ brings the evacuation out in order: gain an Ally and DM+1 to this term’s Advancement. Failure earns the resentment of a stranded officer: gain a Rival.',choices:[check('evacuate','Coordinate the evacuation','Лидерство',3,[rel('Союзник'),mod('advancement',1,'Outpost evacuated')],[rel('Конкурент')])]},
{id:'primitive-assault',career:'marines',number:8,art:'primitive-assault',title:'Assault on a primitive world',text:'Your unit drops above a stone fortress defended by a technologically primitive army. Choose a tactical approach or close combat, then check 8+. Success grants the chosen skill at level 1 and DM+1 to one Other Benefit roll. Failure causes an Injury; after treatment, continue this term.',choices:[check('assault-tactics','Coordinate the assault','Тактика (военная)',3,[skill('Тактика (военная)'),mod('benefit',1,'Primitive-world operation')],[effect('injury',{after:'advancement'})]),check('assault-melee','Lead the breach','Ближний (большой клинок)',1,[skill('Ближний (большой клинок)'),mod('benefit',1,'Primitive-world operation')],[effect('injury',{after:'advancement'})])]},
{id:'primitive-negotiations',career:'army',number:6,art:'primitive-negotiations',title:'A fortress without a battle',text:'Your unit surrounds the fortress of a ruler on a primitive world. Try Diplomat 8+ to arrange a peaceful surrender, gaining Diplomat 1 and a Contact; failure costs DM−1 to Advancement. Alternatively, supervise the cordon without a check and gain Recon 1.',choices:[check('parley','Negotiate a surrender','Дипломатия',4,[skill('Дипломатия'),rel('Контакт')],[mod('advancement',-1,'Negotiations stalled')]),{id:'cordon',label:'Supervise the cordon: Recon 1',...end([skill('Разведка')])}]},
{id:'state-funeral',career:'noble',number:11,art:'state-funeral',title:'A state funeral',text:'You represent your house at the funeral of an influential statesperson. Reconcile the bereaved factions, gaining Diplomat 1, or renew the house’s obligations, gaining an Ally. Choose one; no check is required.',choices:[{id:'reconcile',label:'Reconcile the factions: Diplomat 1',...end([skill('Дипломатия')])},{id:'obligations',label:'Renew an old alliance',...end([rel('Союзник')])}]},
{id:'memorial-performance',career:'entertainer',number:6,art:'memorial-performance',title:'A performance of remembrance',text:'You are invited to perform at a public memorial ceremony. Art 8+ earns a Contact among the organisers and DM+1 to one Other Benefit roll. An ill-judged performance instead gives DM−1 to this term’s Advancement.',choices:[check('memorial','Perform at the ceremony','Искусство',3,[rel('Контакт'),mod('benefit',1,'Memorial commission')],[mod('advancement',-1,'Memorial poorly received')])]},
{id:'orbital-biosphere',career:'scholar',number:4,art:'orbital-biosphere',title:'An orbital biosphere',text:'An orbital research habitat is losing ecological balance. Use Life Science or Engineer 8+ to stabilise it. Success grants the chosen skill at level 1 and a Contact among the researchers. Failure damages valuable samples: DM−1 to one Other Benefit roll.',choices:[check('biosphere-science','Restore the ecological balance','Наука о жизни',4,[skill('Наука о жизни'),rel('Контакт')],[mod('benefit',-1,'Samples lost')]),check('biosphere-engineer','Repair the habitat systems','Инженерия',3,[skill('Инженерия'),rel('Контакт')],[mod('benefit',-1,'Samples lost')])]},
{id:'station-concession',career:'merchant',number:10,art:'station-concession',title:'A station concession',text:'A small orbital habitat offers a long-term supply contract. Broker 8+ secures a Contact and DM+1 to one Other Benefit roll; failure creates a Rival among the competing suppliers. You may decline and continue without a reward or penalty.',choices:[check('concession','Negotiate the supply contract','Брокер',3,[rel('Контакт'),mod('benefit',1,'Orbital supply contract')],[rel('Конкурент')]),{id:'decline-contract',label:'Decline the contract',...end()}]}
];
function forSlot(career,number){return events.find(e=>e.career===career&&e.number===Number(number))||null}
function selected(s){const number=s.phase==='event'?(s.currentRoll?.raw??s.context?.event):s.context?.event;const e=events.find(e=>e.id===s.context?.eventVariant);return e&&e.career===s.activeCareer?.careerId&&e.number===Number(number)?e:null}
function install(R){for(const e of events)R.tables[e.career].events.rows[e.number].additionalEvent=e.id;
Object.assign(R.tables.scholar.mishaps.rows[2],{title:'A research accident',text:'An accident in your research leaves you injured and creates a Rival. Roll twice on the Injury table and use the higher result.'});
Object.assign(R.tables.scholar.mishaps.rows[5],{title:'Research in ruins',text:'Your research is devastated. Salvage what you can and retain this term’s Benefit, or lose all Benefits from this career and remain to start again.'});
}
return {events,forSlot,selected,install};
});
